<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('catalog.view');
$pdo=db();$q=trim((string)($_GET['q']??''));$state=(string)($_GET['state']??'all');$categoryId=max(0,(int)($_GET['category_id']??0));$usage=(string)($_GET['usage']??'all');$sort=(string)($_GET['sort']??'category');$itemType=(string)($_GET['type']??'all');
$where=[];$params=[];if($q!==''){$where[]='(sc.name_es LIKE ? OR sc.name_pt LIKE ? OR sc.name_en LIKE ? OR COALESCE(cat.name,sc.category) LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like,$like);}if($state==='active')$where[]='sc.is_active=1';elseif($state==='inactive')$where[]='sc.is_active=0';if(in_array($itemType,['service','product'],true)){$where[]='sc.item_type=?';$params[]=$itemType;}if($categoryId>0){$where[]='sc.category_id=?';$params[]=$categoryId;}
$usageExpr='(COALESCE(cs.contract_count,0)+COALESCE(qs.quote_count,0))';$lastExpr="GREATEST(COALESCE(cs.last_used_at,'1000-01-01 00:00:00'),COALESCE(qs.last_used_at,'1000-01-01 00:00:00'))";if($usage==='recent30')$where[]="$lastExpr >= DATE_SUB(NOW(),INTERVAL 30 DAY)";elseif($usage==='recent90')$where[]="$lastExpr >= DATE_SUB(NOW(),INTERVAL 90 DAY)";elseif($usage==='used')$where[]="$usageExpr > 0";elseif($usage==='never')$where[]="$usageExpr = 0";
$orderBy=match($sort){'name'=>'sc.name_es ASC','recent'=>"$lastExpr DESC,sc.name_es ASC",'usage'=>"$usageExpr DESC,sc.name_es ASC",'status'=>'sc.is_active DESC,sc.name_es ASC',default=>"COALESCE(NULLIF(cat.name,''),NULLIF(sc.category,''),'Sin categoría') ASC,sc.name_es ASC"};
$joins=" LEFT JOIN service_categories cat ON cat.id=sc.category_id LEFT JOIN (SELECT catalog_service_id,COUNT(*) contract_count,MAX(updated_at) last_used_at FROM client_services WHERE catalog_service_id IS NOT NULL GROUP BY catalog_service_id) cs ON cs.catalog_service_id=sc.id LEFT JOIN (SELECT qi.catalog_service_id,COUNT(*) quote_count,MAX(q.updated_at) last_used_at FROM quotation_items qi JOIN quotations q ON q.id=qi.quotation_id WHERE qi.catalog_service_id IS NOT NULL GROUP BY qi.catalog_service_id) qs ON qs.catalog_service_id=sc.id";$whereSql=$where?' WHERE '.implode(' AND ',$where):'';
$stmt=$pdo->prepare("SELECT sc.*,COALESCE(cat.name,sc.category) category_name,COALESCE(cs.contract_count,0) contract_count,COALESCE(qs.quote_count,0) quote_count,$usageExpr usage_count,NULLIF($lastExpr,'1000-01-01 00:00:00') last_used_at FROM service_catalog sc $joins $whereSql ORDER BY $orderBy");$stmt->execute($params);$rows=$stmt->fetchAll();
$xml='<?xml version="1.0" encoding="UTF-8"?><?mso-application progid="Excel.Sheet"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Styles><Style ss:ID="Header"><Font ss:Bold="1" ss:Color="#FFFFFF"/><Interior ss:Color="#002F57" ss:Pattern="Solid"/></Style><Style ss:ID="Money"><NumberFormat ss:Format="#,##0.00"/></Style></Styles><Worksheet ss:Name="Catalogo"><Table>';
$headers=['ID','Tipo','Categoría','Nombre ES','Nombre PT','Nombre EN','Descripción ES','Descripción PT','Descripción EN','Modalidad','Meses personalizados','Precio CLP','Precio USD','Precio BRL','Servicios de clientes','Cotizaciones','Total usos','Último uso','Estado'];$xml.='<Row>';foreach($headers as$h)$xml.='<Cell ss:StyleID="Header"><Data ss:Type="String">'.htmlspecialchars($h,ENT_XML1|ENT_QUOTES,'UTF-8').'</Data></Cell>';$xml.='</Row>';
foreach($rows as$r){$values=[[$r['id'],'Number'],[$r['item_type']==='product'?'Producto':'Servicio','String'],[$r['category_name'],'String'],[$r['name_es'],'String'],[$r['name_pt'],'String'],[$r['name_en'],'String'],[$r['description_es'],'String'],[$r['description_pt'],'String'],[$r['description_en'],'String'],[contract_label((string)$r['default_contract_type']),'String'],[$r['custom_period_months'],'Number'],[$r['price_clp'],'Number'],[$r['price_usd'],'Number'],[$r['price_brl'],'Number'],[$r['contract_count'],'Number'],[$r['quote_count'],'Number'],[$r['usage_count'],'Number'],[$r['last_used_at']?(new DateTimeImmutable($r['last_used_at']))->format('d/m/Y'):'','String'],[$r['is_active']?'Activo':'Inactivo','String']];$xml.='<Row>';foreach($values as[$value,$type]){$value=$value??'';$xml.='<Cell><Data ss:Type="'.$type.'">'.htmlspecialchars((string)$value,ENT_XML1|ENT_QUOTES,'UTF-8').'</Data></Cell>';}$xml.='</Row>';}
$xml.='</Table></Worksheet></Workbook>';
$filename='catalogo-cotizaciones-socrates-one-'.date('Y-m-d').'.xls';header('Content-Type: application/vnd.ms-excel; charset=UTF-8');header('Content-Disposition: attachment; filename="'.$filename.'"');header('Content-Length: '.strlen($xml));echo $xml;exit;
